# Conversion functions between uncertainty types
def _std_to_var(uncertainty):
    """Convert StdDevUncertainty to VarianceUncertainty."""
    # std -> var: square the values and square the unit
    return VarianceUncertainty(
        uncertainty.array ** 2,
        unit=uncertainty.unit ** 2 if uncertainty.unit is not None else None,
        copy=False
    )


def _var_to_std(uncertainty):
    """Convert VarianceUncertainty to StdDevUncertainty."""
    # var -> std: take square root of values and square root of unit
    return StdDevUncertainty(
        np.sqrt(uncertainty.array),
        unit=np.sqrt(uncertainty.unit) if uncertainty.unit is not None else None,
        copy=False
    )


def _var_to_invvar(uncertainty):
    """Convert VarianceUncertainty to InverseVariance."""
    # var -> invvar: invert the values and invert the unit
    return InverseVariance(
        1.0 / uncertainty.array,
        unit=1.0 / uncertainty.unit if uncertainty.unit is not None else None,
        copy=False
    )


def _invvar_to_var(uncertainty):
    """Convert InverseVariance to VarianceUncertainty."""
    # invvar -> var: invert the values and invert the unit
    return VarianceUncertainty(
        1.0 / uncertainty.array,
        unit=1.0 / uncertainty.unit if uncertainty.unit is not None else None,
        copy=False
    )


def _std_to_invvar(uncertainty):
    """Convert StdDevUncertainty to InverseVariance."""
    # std -> var -> invvar
    return _var_to_invvar(_std_to_var(uncertainty))


def _invvar_to_std(uncertainty):
    """Convert InverseVariance to StdDevUncertainty."""
    # invvar -> var -> std
    return _var_to_std(_invvar_to_var(uncertainty))


