def _convert_to_variance(self):
    data = self.array
    measure_unit = self.unit
    variance_data = data ** 2 if data is not None else None
    variance_unit = measure_unit ** 2 if measure_unit is not None else None
    return VarianceUncertainty(variance_data, unit=variance_unit)

@classmethod
def _convert_from_variance(cls, var_uncert):
    values = var_uncert.array
    unit_of_measure = var_uncert.unit
    standard_deviation_values = values ** 0.5 if values is not None else None
    standard_deviation_unit = unit_of_measure ** 0.5 if unit_of_measure is not None else None
    return cls(standard_deviation_values, unit=standard_deviation_unit)

