    elif version == 'astropyconst20':
        globals().update({k: v for k, v in vars(astropyconst20).items() if isinstance(v, Constant)})
    else:
        raise ValueError("Unknown version")
    return _ConstantsContextManager(version)

class _ConstantsContextManager:
    def __init__(self, version):
        self.version = version
        self.original_constants = {k: v for k, v in globals().items() if isinstance(v, Constant)}

    def __enter__(self):
        constants_set(self.version)

    def __exit__(self, exc_type, exc_value, traceback):
        globals().update(self.original_constants)

