def helper_clip(f, unit1, unit2, unit3):
    conversion_list = [None]
    final_unit = dimensionless_unscaled if unit1 is None else unit1
    target_units = (unit2, unit3)

    for unit in target_units:
        if unit is None:
            conversion_list.append(None)
        else:
            try:
                conversion = get_converter(unit, final_unit)
            except UnitsError:
                if unit is not None:
                    raise UnitConversionError(
                        "Function '{0}' can only process quantities with matching dimensions".format(f.__name__)
                    )
                # acceptable if the second or third unit is a unitless number
                conversion_list.append(False)
            else:
                conversion_list.append(conversion)

    return conversion_list, final_unit

def helper_clip(f, unit1, unit2, unit3):
