def none_guard(func):
    """
    Decorator returning None when any argument of the decorated function is
    None, since many SQL functions return NULL when one of their arguments is
    NULL.  It keeps the custom functions registered below simple.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if None in args:
            return None
        return func(*args, **kwargs)
    return wrapper

def none_guard(func):
    """
    Decorator that returns None if any of the arguments to the decorated
    function are None. Many SQL functions return NULL if any of their arguments
    are NULL. This decorator simplifies the implementation of this for the
    custom functions registered below.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return None if None in args else func(*args, **kwargs)
    return wrapper

