def clean(self, value):
    """
    Validate that the given value exists in the queryset, unless the field
    is disabled, in which case we don't validate the value.
    """
    if self.disabled:
        # For disabled fields, return the prepared value without validation
        value = self.prepare_value(value)
        if value in self.empty_values:
            return None
        # Try to fetch the object, but don't fail if we can't
        try:
            key = self.to_field_name or 'pk'
            return self.queryset.get(**{key: value})
        except (ValueError, TypeError, self.queryset.model.DoesNotExist):
            # For disabled fields, return the value as-is even if validation fails
            return value
    return super().clean(value)

