def is_django_path(file_path):
    """Check if the provided file path is located inside Django's directory structure."""
    django_root = Path(django.__file__).resolve().parent
    resolved_path = Path(file_path).resolve()
    return any(parent == django_root for parent in resolved_path.parents)

