                        constraint_attr, part
                    ),
                    hint="Constraints can only reference fields on the current model.",
                    obj=cls,
                    id='models.E042',
                )
            )
    return errors

@classmethod
def _get_query_parts_from_q(cls, q_obj):
    """
    Extract all field lookups from a Q object that contain LOOKUP_SEP (joins).
    """
    parts = []
    if isinstance(q_obj, Q):
        for child in q_obj.children:
            if isinstance(child, Q):
                parts.extend(cls._get_query_parts_from_q(child))
