def _resolve_output_field(self):
    """
    Determine the output field for combined expressions, with special
    handling for temporal subtraction and duration arithmetic.
    """
    try:
        lhs_type = self.lhs.output_field.get_internal_type()
    except FieldError:
        lhs_type = None
    try:
        rhs_type = self.rhs.output_field.get_internal_type()
    except FieldError:
        rhs_type = None

    # Handle temporal subtraction: DateField/DateTimeField/TimeField - same type = DurationField
    datetime_fields = {'DateField', 'DateTimeField', 'TimeField'}
    if self.connector == self.SUB and lhs_type in datetime_fields and lhs_type == rhs_type:
        return fields.DurationField()

    # Handle duration arithmetic: when one side is DurationField, result is DurationField
    if lhs_type == 'DurationField' or rhs_type == 'DurationField':
        return fields.DurationField()

    # Fall back to default behavior
    return super()._resolve_output_field()

