    validation_issues = []
    for database in databases:
        if not router.allow_migrate_model(database, self.model):
            continue
        db_connection = connections[database]
        feature_requirements = self.model._meta.required_db_features
        supports_collation = (
            'supports_collation_on_charfield' in feature_requirements or
            db_connection.features.supports_collation_on_charfield
        )
        if self.db_collation and not supports_collation:
            validation_issues.append(
