                formatted_values = tuple(f"{json_func(value)}('{json.dumps({'value': value})}', '$.value')" for value in values)
                rhs_params = ()
                rhs = rhs % formatted_values
            elif connection.vendor == 'mysql' and connection.mysql_is_mariadb:
                rhs = rhs % (("JSON_UNQUOTE(JSON_EXTRACT(%s, '$'))",) * len(rhs_params))
