def _resolve_expression_to_annotations(self, expression, query):
    """
    Resolve F expressions in an aggregate to use annotation names
    when the referenced field has been annotated.
    """
    if isinstance(expression, F):
        # Check if this F expression references a field that has been annotated
        field_name = expression.name
        if field_name in query.annotations:
            # Replace with F expression pointing to the annotation
            return F(field_name)

    # For complex expressions, recursively resolve their parts
    if hasattr(expression, 'source_expressions') and expression.source_expressions:
        new_source_expressions = []
        for source_expr in expression.source_expressions:
            new_source_expressions.append(
                self._resolve_expression_to_annotations(source_expr, query)
            )
        expression = expression._copy_to(
            expression.__class__(*new_source_expressions)
        ) if hasattr(expression, '_copy_to') else expression.copy()
        expression.source_expressions = new_source_expressions

    return expression

