def __deepcopy__(self, memo):
    obj = type(self)()
    obj.connector = self.connector
    obj.negated = self.negated
    # Deepcopy children, converting non-pickleable iterables to lists
    for child in self.children:
        if isinstance(child, Q):
            obj.children.append(copy.deepcopy(child, memo))
        elif isinstance(child, tuple) and len(child) == 2:
            # This is a (key, value) tuple from kwargs
            key, value = child
            # Convert non-pickleable types to pickleable ones
            if hasattr(value, '__iter__') and not isinstance(value, (str, bytes)):
                try:
                    # Try to pickle it
                    copy.deepcopy(value, memo)
                    obj.children.append((key, copy.deepcopy(value, memo)))
                except TypeError:
                    # If it fails, convert to list
                    obj.children.append((key, list(value)))
            else:
                obj.children.append((key, copy.deepcopy(value, memo)))
        else:
            obj.children.append(copy.deepcopy(child, memo))
    memo[id(self)] = obj
    return obj

