def _check_db_table_comment(cls, database_list):
    table_comment_missing = not cls._meta.db_table_comment
    if table_comment_missing:
        return []

    validation_issues = []
    for database in database_list:
        migration_allowed = router.allow_migrate_model(database, cls)
        if not migration_allowed:
            continue

    db_connection = connections[database]
    comment_support_available = (
        db_connection.features.supports_comments
        or "supports_comments" in cls._meta.required_db_features
    )
    if not comment_support_available:
        warning_message = f"{db_connection.display_name} does not support comments on tables (db_table_comment)."
        validation_issues.append(
            checks.Warning(
                warning_message,
                obj=cls,
                id="models.W046",
            )
        )

    return validation_issues

