    try:
        yield
    finally:
        if connection.queries_logged:
            elapsed_time = time.monotonic() - initial_time
            log_entry = {
                "sql": query,
                "time": f"{elapsed_time:.3f}",
            }
            connection.queries_log.append(log_entry)
            logger.debug(
                "(%.3f) %s; args=None; alias=%s",
                elapsed_time,
                query,
                connection.alias,
                extra={
