def _parse_srcset(items):
    """
    Converts srcset entries into a dictionary linking multipliers to their respective entries.
    """
    result = dict()
    for item in items:
        trimmed_item = item.strip()
        if len(trimmed_item) > 1:
            multiplier = trimmed_item.rstrip('x')
            result[float(multiplier)] = trimmed_item
        else:
            raise ExtensionError(f'Invalid srcset entry: {item!r}')
    return result

def _parse_srcset(entries):
    """
    Parse srcset for multiples...
    """
    srcset = {}
    for entry in entries:
        entry = entry.strip()
        if len(entry) >= 2:
            mult = entry[:-1]
            srcset[float(mult)] = entry
        else:
            raise ExtensionError(f'srcset argument {entry!r} is invalid.')
    return srcset

