def merge_cookies(cookie_jar, cookie_data):
    """Integrates provided cookies into the existing cookie jar and returns it.

    :param cookie_jar: Existing CookieJar instance to receive additional cookies.
    :param cookie_data: New cookies, either as a dictionary or another CookieJar.
    """
    if not isinstance(cookie_jar, cookielib.CookieJar):
        raise ValueError('Destination must be a CookieJar')

    if isinstance(cookie_data, dict):
        augmented_jar = cookiejar_from_dict(cookie_data, cookiejar=cookie_jar, overwrite=False)
    elif isinstance(cookie_data, cookielib.CookieJar):
        try:
            cookie_jar.update(cookie_data)
        except AttributeError:
            for single_cookie in cookie_data:
                cookie_jar.set_cookie(single_cookie)

    return cookie_jar

def merge_cookies(cookiejar, cookies):
    """Add cookies to cookiejar and returns a merged CookieJar.

    :param cookiejar: CookieJar object to add the cookies to.
    :param cookies: Dictionary or CookieJar object to be added.
    """
    if not isinstance(cookiejar, cookielib.CookieJar):
        raise ValueError('You can only merge into CookieJar')

    if isinstance(cookies, dict):
        cookiejar = cookiejar_from_dict(
            cookies, cookiejar=cookiejar, overwrite=False)
    elif isinstance(cookies, cookielib.CookieJar):
        try:
            cookiejar.update(cookies)
        except AttributeError:
            for cookie_in_jar in cookies:
                cookiejar.set_cookie(cookie_in_jar)

    return cookiejar

