def _get_shape_from_coords_and_dims(
    coords: Any, dims: Any
) -> Optional[Tuple[int, ...]]:
    """Infer the shape of an array from coords and dims.

    Returns None if shape cannot be inferred.
    """
    # Handle case where dims is a single string
    if isinstance(dims, str):
        dims = (dims,)

    # If we have dict-like coords, we can infer shape from them
    if is_dict_like(coords):
        if dims is not None:
            sizes = {}
            for dim in dims:
                if dim in coords:
                    coord_data = coords[dim]
                    # Handle Variable, DataArray, or array-like
                    if hasattr(coord_data, "shape"):
                        sizes[dim] = coord_data.shape[0]
                    elif hasattr(coord_data, "__len__"):
                        sizes[dim] = len(coord_data)
                    else:
                        # Can't infer size
                        return None
            if len(sizes) == len(dims):
                return tuple(sizes[dim] for dim in dims)
    elif coords is not None and not is_dict_like(coords):
        # coords is a sequence of array-like objects
        if dims is not None and len(coords) == len(dims):
            sizes = []
            for coord in coords:
                if hasattr(coord, "shape"):
                    sizes.append(coord.shape[0])
                elif hasattr(coord, "__len__"):
                    sizes.append(len(coord))
                else:
                    # Can't infer size
                    return None
            return tuple(sizes)

    return None

