def limit_lines(string: str, *, limit: int):
    """
    Return the string unchanged unless it has more lines than the limit, in
    which case the middle lines are replaced by an ellipsis.
    """
    lines = string.splitlines()
    if len(lines) <= limit:
        return string
    half_limit = limit // 2
    return "\n".join(lines[:half_limit] + ["..."] + lines[-half_limit:])

