def maybe_coerce_to_str(index, original_coords):
    """Convert a pandas Index to a numpy array of strings if coordinates suggest it.

    pandas Index stores strings with object dtype; this function aims to convert
    to string dtype if applicable.
    """
    try:
        dtype_kind = dtypes.result_type(*original_coords).kind
    except TypeError:
        return index
    if dtype_kind in "SU":
        index = np.asarray(index, dtype=dtypes.result_type(*original_coords).type)
    return index

def maybe_coerce_to_str(index, original_coords):
    """maybe coerce a pandas Index back to a nunpy array of type str

    pd.Index uses object-dtype to store str - try to avoid this for coords
    """

    try:
        result_type = dtypes.result_type(*original_coords)
    except TypeError:
        pass
    else:
        if result_type.kind in "SU":
            index = np.asarray(index, dtype=result_type.type)

    return index

