def _is_typing_import(node):
    """Check if an import is within a TYPE_CHECKING block"""
    current = node
    while current is not None:
        if isinstance(current, astroid.If):
            # Check if this is a TYPE_CHECKING condition
            test = current.test
            if isinstance(test, astroid.Name) and test.name == "TYPE_CHECKING":
                return True
            if isinstance(test, astroid.Attribute):
                if test.attrname == "TYPE_CHECKING":
                    return True
        current = current.parent
    return False

