def _order_all_first(config_args: list[str], *, joined: bool) -> list[str]:
    """Rearrange configuration arguments to prioritize --enable=all or --disable=all.

    Throw an exception if both options are provided.

    When joined is True, anticipate arguments like '--enable=all,for-any-all'.
    When joined is False, anticipate separate arguments such as '--enable', 'all,for-any-all'.
    """
    indices_to_front = []
    previous_all_directive = None

    for index, argument in enumerate(config_args):
        if joined and argument.startswith(("--enable=", "--disable=")):
            parts = argument.split("=")
            directive, options = parts[0], parts[1]
        elif argument in ("--enable", "--disable"):
            directive = argument
            options = config_args[index + 1]
        else:
            continue

        if any(option.strip() == "all" for option in options.split(",")):
            if previous_all_directive and directive != previous_all_directive:
                raise ArgumentPreprocessingError(
                    "Cannot specify both --enable=all and --disable=all."
                )
            previous_all_directive = directive

            indices_to_front.append(index)
            if not joined:
                indices_to_front.append(index + 1)

    rearranged_arguments = [config_args[idx] for idx in indices_to_front]
    rearranged_arguments.extend(
        config_args[i] for i in range(len(config_args)) if i not in indices_to_front
    )

    return rearranged_arguments

def _order_all_first(config_args: list[str], *, joined: bool) -> list[str]:
    """Reorder config_args such that --enable=all or --disable=all comes first.

    Raise if both are given.

    If joined is True, expect args in the form '--enable=all,for-any-all'.
    If joined is False, expect args in the form '--enable', 'all,for-any-all'.
    """
    indexes_to_prepend = []
    all_action = ""

    for i, arg in enumerate(config_args):
        if joined and (arg.startswith("--enable=") or arg.startswith("--disable=")):
            value = arg.split("=")[1]
        elif arg in {"--enable", "--disable"}:
            value = config_args[i + 1]
        else:
            continue

        if "all" not in (msg.strip() for msg in value.split(",")):
            continue

        arg = arg.split("=")[0]
        if all_action and (arg != all_action):
            raise ArgumentPreprocessingError(
                "--enable=all and --disable=all are incompatible."
            )
        all_action = arg

        indexes_to_prepend.append(i)
        if not joined:
            indexes_to_prepend.append(i + 1)

    returned_args = []
    for i in indexes_to_prepend:
        returned_args.append(config_args[i])

    for i, arg in enumerate(config_args):
        if i in indexes_to_prepend:
            continue
        returned_args.append(arg)

    return returned_args

def _check_regexp_csv(value: list[str] | tuple[str] | str) -> Iterable[str]:
    r"""Split a comma-separated list of regexps, taking care to avoid splitting
    a regex employing a comma as quantifier, as in `\d{1,2}`."""
    parts = []
    current_part = []
    brace_depth = 0

    for char in value:
        if char == "{":
            brace_depth += 1
        elif char == "}":
            brace_depth -= 1

        if char == "," and brace_depth == 0:
            parts.append("".join(current_part).strip())
            current_part = []
        else:
            current_part.append(char)

    parts.append("".join(current_part).strip())
    yield from (part for part in parts if part)

