def _precompute_metric_params(X, Y, metric=None, **kwds):
    """Calculate and return necessary metric-specific parameters if not given."""
    if metric == "seuclidean" and 'V' not in kwds:
        dataset = X if X is Y else np.vstack((X, Y))
        variance = np.var(dataset, axis=0, ddof=1)
        return {'V': variance}
    elif metric == "mahalanobis" and 'VI' not in kwds:
        combined_data = X if X is Y else np.vstack((X, Y))
        inverse_covariance = np.linalg.inv(np.cov(combined_data.T)).T
        return {'VI': inverse_covariance}
    return {}

def _precompute_metric_params(X, Y, metric=None, **kwds):
    """Precompute data-derived metric parameters if not provided
    """
    if metric == "seuclidean" and 'V' not in kwds:
        if X is Y:
            V = np.var(X, axis=0, ddof=1)
        else:
            V = np.var(np.vstack([X, Y]), axis=0, ddof=1)
        return {'V': V}
    if metric == "mahalanobis" and 'VI' not in kwds:
        if X is Y:
            VI = np.linalg.inv(np.cov(X.T)).T
        else:
            VI = np.linalg.inv(np.cov(np.vstack([X, Y]).T)).T
        return {'VI': VI}
    return {}

