                       builder: "Builder", link_type: str, link_target: str,
                       node: pending_xref, display_node: Element) -> Element:
    resolved_element = self._resolve_obj_xref(env, source_doc, builder, link_type,
                                             link_target, node, display_node)
    if resolved_element:
        return resolved_element
    else:
        match_found = False
        for object_type, term in self.objects:
            if object_type == 'term' and term.lower() == link_target.lower():
                doc_id, label_id = self.objects[object_type, term]
                logger.warning(__('%s term not directly found; '
                                  'referencing %s instead.'), link_target, term,
                               location=node, type='reference', subtype='term')
                match_found = True
                break
        if not match_found:
            doc_id, label_id = '', ''
        if not doc_id:
            return None
        return make_refnode(builder, source_doc, doc_id,
                            label_id, display_node)

