    for field in fields:
        param_info = field[0].astext().split(' ')
        param_kind = param_info[0]
        param_name = ' '.join(param_info[2:]) if len(param_info) > 2 else param_info[1] if len(param_info) == 2 else ''

        if param_kind == 'param':
            described_params.add(param_name)
            if len(param_info) > 2:
                typed_params.add(param_name)
        elif param_kind == 'type':
            typed_params.add(' '.join(param_info[1:]))
        elif param_kind == 'return':
            described_params.add('return')
        elif param_kind == 'rtype':
            typed_params.add('return')

    for parameter in annotations:
        if parameter == 'return' or parameter in typed_params:
            continue
