def find_common_elements_in_pairs(set_collection):
    from itertools import combinations
    from collections import defaultdict
    optimal_combinations = defaultdict(list)
    max_overlap_size = -1
    for idx1, idx2 in combinations(range(len(set_collection)), 2):
        common_elements = set_collection[idx1].intersection(set_collection[idx2])
        overlap_size = len(common_elements)
        if overlap_size > max_overlap_size:
            optimal_combinations.clear()
            max_overlap_size = overlap_size
        if overlap_size == max_overlap_size:
            optimal_combinations[frozenset(common_elements)].append((idx1, idx2))
    result = [(k, v) for k, v in optimal_combinations.items()]
    result.sort(key=lambda x: len(x[1]))
    return result


