def _minmax_as_Piecewise(comparison, *operands):
    from sympy.functions.elementary.piecewise import Piecewise
    conditions = []
    for idx, operand in enumerate(operands):
        checks = []
        for other_idx in range(idx + 1, len(operands)):
            checks.append(Relational(operand, operands[other_idx], comparison))
        conditions.append((operand, And(*checks)))
    return Piecewise(*conditions)

def _minmax_as_Piecewise(op, *args):
    # helper for Min/Max rewrite as Piecewise
    from sympy.functions.elementary.piecewise import Piecewise
    ec = []
    for i, a in enumerate(args):
        c = []
        for j in range(i + 1, len(args)):
            c.append(Relational(a, args[j], op))
        ec.append((a, And(*c)))
    return Piecewise(*ec)

