def _print_ConditionSet(self, set_expr):
    symbol_representation = self._print(set_expr.sym)
    condition_description = self._print(set_expr.condition)
    universal_check = set_expr.base_set == S.UniversalSet
    if universal_check:
        formatted_output = 'ConditionSet({}, {})'.format(symbol_representation, condition_description)
    else:
        base_set_representation = self._print(set_expr.base_set)
        formatted_output = 'ConditionSet({}, {}, {})'.format(symbol_representation, condition_description, base_set_representation)
    return formatted_output

def _print_ConditionSet(self, s):
    args = tuple([self._print(i) for i in (s.sym, s.condition)])
    if s.base_set is S.UniversalSet:
        return 'ConditionSet(%s, %s)' % args
    args += (self._print(s.base_set),)
    return 'ConditionSet(%s, %s, %s)' % args

