def find(target, formula):
    """
    Determine if 'target' is included within 'formula'.
    In case of inclusion, return 'target' as a free variable;
    otherwise, raise a ValueError.
    """

    symbols = formula.free_symbols
    matches = [symbol for symbol in symbols if (symbol.name if isinstance(target, str) else symbol) == target]
    if not matches:
        raise ValueError(f"'{target}' not found")
    if len(matches) > 1:
        raise ValueError(f"Multiple instances of '{target}' found")
    return matches[0]

