def __getattr__(self, name):
    """
    Support accessing naxisj attributes dynamically for j >= 3.
    """
    if name.startswith('naxis') and name[5:].isdigit():
        axis_num = int(name[5:]) - 1
        if axis_num >= 0:
            if axis_num < len(self._naxis):
                return self._naxis[axis_num]
            else:
                return 0
    raise AttributeError("'{0}' object has no attribute '{1}'".format(
        self.__class__.__name__, name))

def __setattr__(self, name, value):
    """
    Support setting naxisj attributes dynamically for j >= 3.
    """
    if name.startswith('naxis') and name[5:].isdigit() and name not in ('naxis1', 'naxis2'):
        axis_num = int(name[5:]) - 1
        if axis_num >= 0:
            # Ensure _naxis list is large enough
            while len(self._naxis) <= axis_num:
                self._naxis.append(0)
            self._naxis[axis_num] = value
            return
    super(WCS, self).__setattr__(name, value)

