def convert_jsonfield_value(self, value, expression, connection):
    # For JSONField, we need to handle boolean conversions from KeyTransform
    # SQLite's JSON_EXTRACT returns 1/0 for booleans instead of True/False
    if value in (1, 0):
        # Check if this is from a KeyTransform extraction
        from django.db.models.fields.json import KeyTransform
        if isinstance(expression, KeyTransform):
            # We need to check the actual JSON value to see if it's truly a boolean
            # When JSON has true/false, JSON_EXTRACT returns 1/0, so we convert back
            return bool(value)
    return value

