    if self._wrapped is empty:
        self._setup()
    return other / self._wrapped

def __rfloordiv__(self, other):
    if self._wrapped is empty:
        self._setup()
    return other // self._wrapped

def __rmod__(self, other):
    if self._wrapped is empty:
        self._setup()
    return other % self._wrapped

def __rpow__(self, other):
    if self._wrapped is empty:
        self._setup()
    return other ** self._wrapped

