def reduce(self, operation, app_label):
    if (
        isinstance(operation, AddIndex)
        and self.name_lower == operation.model_name_lower
    ):
        # Check if this AddIndex operation replaces an index_together constraint
        if self.option_value:
            # Convert index.fields to a frozenset for comparison with index_together tuples
            added_fields = frozenset(operation.index.fields)
            # Remove matching index_together entries
            remaining_together = {
                fields
                for fields in self.option_value
                if frozenset(fields) != added_fields
            }
            if remaining_together != self.option_value:
                # Some index_together entries were replaced by AddIndex
                if remaining_together:
                    return [
                        AlterIndexTogether(self.name, remaining_together),
                        operation,
                    ]
                else:
                    # All index_together entries have been replaced
                    return [operation]
    return super().reduce(operation, app_label)

