    """Return state for pickling.

    Convert weak references to strong references for pickling.
    """
    # Clean up dead references first
    self.clean()
    # Convert weak references back to strong references
    state = {}
    for key_ref, group_refs in self._mapping.items():
        key_obj = key_ref()
        if key_obj is not None:
            group_objs = [ref() for ref in group_refs]
            # Only include non-None objects
            group_objs = [obj for obj in group_objs if obj is not None]
            if group_objs:
                state[id(key_obj)] = (key_obj, group_objs)
    return {'state': state}

