def any_fail_on_issues(self):
    """Check if any issues matching the fail-on criteria were found.

    Returns True if any messages matching the fail-on list were reported,
    False otherwise.
    """
    if not self.config.fail_on:
        return False

    fail_on_list = self.config.fail_on

    # Check each message that was added during linting
    # We need to check the stats to see if any messages from fail_on categories were found
    for msg_category in fail_on_list:
        # Check if it's a message category (single letter like E, W, etc.)
        if len(msg_category) == 1 and msg_category.isupper():
            # It's a category - check if any messages in that category were found
            if self.stats.get(msg_category, 0) > 0:
                return True
        else:
            # It's a message symbol/id - check if that specific message was found
            # Look through the message store to find the msgid for this symbol
            for message in self.msgs_store.messages:
                if message.symbol == msg_category or message.msgid == msg_category:
                    if self.stats.get("by_msg", {}).get(message.msgid, 0) > 0:
                        return True
                    break

    return False

