@staticmethod
def _handle_function_annotations(node):
    """Extract type hints from function annotations and add to locals_type"""
    if not hasattr(node, "args") or not node.args:
        return
    # Process argument annotations
    for arg in node.args.args:
        if arg.annotation:
            try:
                # Try to infer the annotation
                values = set(arg.annotation.infer())
                if values and values != {astroid.Uninferable}:
                    current = set(node.locals_type.get(arg.name, []))
                    node.locals_type[arg.name] = list(current | values)
            except astroid.InferenceError:
                pass
    # Process return annotation
    if node.returns:
        try:
            values = set(node.returns.infer())
            if values and values != {astroid.Uninferable}:
                current = set(node.locals_type.get("return", []))
                node.locals_type["return"] = list(current | values)
        except astroid.InferenceError:
            pass


    # Add type hints from __init__ function parameters
    if "__init__" in node:
        init_func = node["__init__"][0]
        if isinstance(init_func, astroid.FunctionDef):
            attrs.extend(self._get_init_params_attrs(init_func))


def _get_init_params_attrs(self, init_func):
    """Extract parameter type hints from __init__ function"""
    attrs = []
    if not hasattr(init_func, "args") or not init_func.args:
        return attrs

    for arg in init_func.args.args:
        if arg.name == "self":
            continue
        if not self.show_attr(arg.name):
            continue

        # Check if parameter has annotation
        if arg.annotation:
            try:
                inferred = list(arg.annotation.infer())
                names = []
                for inf in inferred:
                    if inf is astroid.Uninferable:
                        continue
                    if isinstance(inf, astroid.Instance):
                        inf = inf._proxied
                    if isinstance(inf, astroid.ClassDef) and hasattr(inf, "name"):
                        if inf.name not in names:
                            names.append(inf.name)

                if names:
                    attr_str = "{} : {}".format(arg.name, ", ".join(names))
                    attrs.append(attr_str)
            except astroid.InferenceError:
                pass

    return attrs

    # process type hints from __init__ parameters
    self._handle_init_annotations(node)

@staticmethod
def _handle_init_annotations(node):
    """Extract type hints from __init__ function parameters"""
    if "__init__" not in node:
        return
    init_methods = node["__init__"]
    if not init_methods:
        return
    init_func = init_methods[0]
    if not isinstance(init_func, astroid.FunctionDef):
        return
    if not hasattr(init_func, "args") or not init_func.args:
        return

    for arg in init_func.args.args:
        if arg.name == "self" or not arg.annotation:
            continue
        try:
            values = set(arg.annotation.infer())
            if values and astroid.Uninferable not in values:
                current = set(node.instance_attrs_type.get(arg.name, []))
                node.instance_attrs_type[arg.name] = list(current | values)
        except astroid.InferenceError:
            pass

