def show_versions():
    """Print useful debugging information.

    This includes versions of sklearn, numpy, scipy and matplotlib,
    as well as information about the system and the BLAS/LAPACK setup
    that numpy is using.
    """
    import platform

    def _get_deps_info():
        """Get dependency versions."""
        deps = {
            'scikit-learn': __version__,
        }

        # Try to get versions of key dependencies
        try:
            import numpy
            deps['numpy'] = numpy.__version__
        except ImportError:
            deps['numpy'] = None

        try:
            import scipy
            deps['scipy'] = scipy.__version__
        except ImportError:
            deps['scipy'] = None

        try:
            import matplotlib
            deps['matplotlib'] = matplotlib.__version__
        except ImportError:
            deps['matplotlib'] = None

        try:
            import pandas
            deps['pandas'] = pandas.__version__
        except ImportError:
            deps['pandas'] = None

        try:
            import Cython
            deps['Cython'] = Cython.__version__
        except ImportError:
            deps['Cython'] = None

        return deps

    def _get_blas_info():
        """Get BLAS/LAPACK info from numpy."""
        try:
            import numpy
            from numpy.__config__ import show as numpy_show
            import sys
            from io import StringIO

            # Capture numpy's BLAS/LAPACK info
            old_stdout = sys.stdout
            sys.stdout = StringIO()
            try:
                numpy_show()
                output = sys.stdout.getvalue()
                sys.stdout = old_stdout
                return output
            except Exception:
                sys.stdout = old_stdout
                return None
        except ImportError:
            return None

    print('System:')
    print('    python: %s' % platform.python_version())
    print('executable: %s' % sys.executable)
    print('   machine: %s' % platform.platform())

