def _ast_unparse_num(node: Optional[ast.AST]) -> Optional[str]:
    """Unparse an AST node, preserving numeric literal format (hex, oct, bin)."""
    if node is None:
        return None

    # Check if this is a numeric constant node
    if isinstance(node, ast.Num):  # Python < 3.8
        # For older Python versions, we can't easily preserve the format
        return repr(node.n)
    elif isinstance(node, ast.Constant) and isinstance(node.value, int):  # Python >= 3.8
        # For Python 3.8+, Constant nodes are used for all literals
        # We need to check if the value looks like it might have been hex/oct/bin
        # Since AST doesn't preserve this, we fall back to the value itself
        # But we can check the original representation if available
        return repr(node.value)
    else:
        # For non-numeric nodes, use regular unparsing
        return ast_unparse(node)

def _process_type_aliases(annotations: Dict[str, str], autodoc_type_aliases: Dict[str, str]) -> Dict[str, str]:
    """Apply autodoc_type_aliases to annotations."""
    if not autodoc_type_aliases:
        return annotations

    processed = {}
    for name, annotation in annotations.items():
        # Replace type aliases in the annotation string
        processed_annotation = annotation
        for alias, replacement in autodoc_type_aliases.items():
            # Match the alias as a whole word to avoid partial replacements
            processed_annotation = re.sub(
                r'\b' + re.escape(alias) + r'\b',
                replacement,
                processed_annotation
            )
        processed[name] = processed_annotation

    return processed

