@classmethod
def _fold_piecewise_args(cls, args):
    """Fold nested Piecewise expressions in arguments."""
    folded_args = []
    for expr, cond in args:
        if isinstance(expr, Piecewise):
            # Fold the nested piecewise with the current condition
            for e, c in expr.args:
                folded_args.append(ExprCondPair(e, And(c, cond)))
            # If the nested piecewise had a True condition and we haven't
            # reached a True condition yet, we're done with this branch
            if any(c == true for e, c in expr.args):
                if cond == true:
                    break
            continue
        folded_args.append(ExprCondPair(expr, cond))
        if cond == true:
            break
    return folded_args

