def visit_Compare(self, node):
    # Handle relational operators: <, >, <=, >=, ==, !=
    # For now, we only handle single comparisons (e.g., a < b)
    # Multiple comparisons like (a < b < c) are handled by recursion
    if len(node.ops) == 1 and node.ops[0].__class__ in self.comparisons:
        sympy_class = self.comparisons[node.ops[0].__class__]
        left = self.visit(node.left)
        right = self.visit(node.comparators[0])

        new_node = ast.Call(
            func=ast.Name(id=sympy_class, ctx=ast.Load()),
            args=[left, right],
            keywords=[ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load()))],
            starargs=None,
            kwargs=None
